import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',**kw):
 A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage='recognized',issuer_treatment=s,**kw)]))
add(284,'VIE AM consolidées : investissements 3,509 Md$, dette subscription lines 1,443 Md$, maturité moyenne 0,24 an ; actifs cloisonnés par véhicule et sans recours au groupe selon cette note. AM VIE non consolidées : exposition maximale 453 M$, avec possible reprise des performance allocations distincte. Retraite non-consolidated table 134,992 Md$ de portage / 151,099 Md$ de risque maximal inclut fonds sous VIE consolidées ; engagements déjà inclus. Périmètre Apollo après éliminations diffère d’Athene standalone. Pas attribution des portefeuilles génériques à WHCO/IA.','The assets of consolidated VIEs are not available to creditors of the Company','vie_ringfencing_and_scope_specific_maximum_loss',judgment_sensitive=True)
add(285,'Fin 2025 créances affiliées 663 M$ et dettes 1,062 Md$, dont TRA 781 M$ ; Bridge 383 M$ de TRA initial acquis, ne pas ajouter au stock final. TRA porte sur 85% d’économies fiscales réalisées, pas 85% du prix d’investissement. Clawback GP reconnu 212 M$ et créance employés hypothétique 91 M$, règlement seulement après réalisation finale. Engagement Athora AM additionnel jusqu’à 2 Md$ conditionnel distinct des 2,7 Md$ Athene : financement final susceptible de changer. AAA Lux et ACRA déjà consolidés ; AAA NCI +2 Md$ n’est pas une collecte inférée. ARI acquisition ~9 Md$ signée janvier, remplacée par clôture avril dans notes suivantes.','The actual determination and any required payment would not take place until the final disposition of a fund’s investments','related_party_tra_clawback_contingent_cash_and_athora_commitments',judgment_sensitive=True)
add(286,'Apollo consolide Athene ; Bridge acquis le 2 septembre 2025 en échange d’actions, résultats consolidés seulement depuis cette date. Ne pas compter cette acquisition comme apport cash neuf à la chaîne IA.','in an all-stock transaction','bridge_acquisition_stock_not_cash','context_only')
add(287,'Segment Income 6,227 Md$ et revenus segment 20,209 Md$ ne mesurent pas la liquidité ; GAAP revenus 32,049 Md$ et actifs 460,949 Md$ après fonds/VIE/éliminations. AM frais 3,391 Md$ incluent 1,441 Md$ intragroupe Athene ; éliminer pour total externe. PII 338 M$ et realized fees 1,198 Md$ peuvent inclure actions reçues. SRE 3,361 Md$ exclut certains effets marché/NCI ; 560 M$ financement inclut dividendes préférentiels, pas uniquement intérêts cash. HoldCo financement 143 M$ exclu du Segment Income.','We use Segment Income as a measure of operating performance, not as a measure of liquidity.','non_gaap_segments_intercompany_fees_cash_reconciliation',judgment_sensitive=True)
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
 t=json.loads(Path(M[a['index']]['path']).read_text())['text']
 for r in a['rows']:assert r['quote'] in t,(a['index'],r['quote'])
